SELECT platform AS `운영체제`, if(coalesce(source, '') != '', source, if(platform = 'ios', 'iOS: 출처 확인 불가', '출처 확인 불가')) AS `유입 채널`, coalesce(medium, '') AS `매체`, coalesce(campaign, '') AS `캠페인`, count() AS `실행한 통계참여 설치ID` FROM (SELECT distinct_id, argMax(properties.platform, timestamp) AS platform, argMaxIf(toString(properties.utm_source), timestamp, event = 'install_attribution') AS source, argMaxIf(toString(properties.utm_medium), timestamp, event = 'install_attribution') AS medium, argMaxIf(toString(properties.utm_campaign), timestamp, event = 'install_attribution') AS campaign, maxIf(timestamp, event = 'app_opened') AS last_open FROM events WHERE timestamp >= now() - INTERVAL 365 DAY AND properties.client = 'seodang-capacitor' AND properties.environment = 'production' AND event IN ('app_opened','install_attribution') GROUP BY distinct_id HAVING last_open >= now() - INTERVAL 30 DAY) GROUP BY platform, source, medium, campaign ORDER BY `실행한 통계참여 설치ID` DESC
